<?php
/**  SMTP & Mail Log - Admin UI (hooks the admin hook, as every enabled plugin must). */
if (empty($GLOBALS['adminarea'])) return;
add_menu_item('dashboard', ['name'=>'nexa-smtp','class'=>(($_GET['plugin_page']??'')==='nexa-smtp')?'active':'','icon'=>'fa fa-paper-plane-o fa-fw','label'=>' SMTP & Mail Log','link'=>'admin.php?plugin_page=nexa-smtp'], 56);
add_action('nexa_admin','nexa_smtp_admin_render'); add_action('di_admin','nexa_smtp_admin_render'); add_action('up_admin','nexa_smtp_admin_render');
function nexa_smtp_admin_render(): void { static $done=false; if($done) return; if(($_GET['plugin_page']??'')!=='nexa-smtp') return; $done=true;
    nexa_smtp_ensure();
    if(($_SERVER['REQUEST_METHOD']??'')==='POST' && nexa_verify_csrf()){ if(($_POST['do']??'')==='test'){ $ok=nexa_mail(trim((string)$_POST['test_to']),'NexaCMS SMTP Test','Your NexaCMS mail settings work. Sent '.date('Y-m-d H:i:s')); echo '<div class="alert alert-'.($ok?'success':'danger').'">Test email '.($ok?'sent (check inbox/spam)':'failed on this server - check PHP mail / SMTP').'.</div>'; } else { foreach(['smtp_host','smtp_port','smtp_user','smtp_from'] as $k) set_setting($k,trim((string)$_POST[$k])); if(trim((string)($_POST['smtp_pass']??''))!=='') set_setting('smtp_pass',(string)$_POST['smtp_pass']); echo '<div class="alert alert-success">Mail settings saved.</div>'; } }
    echo '<h2><i class="fa fa-paper-plane-o"></i> SMTP &amp; Mail Log</h2><form method="post">'.nexa_csrf_field(); foreach([['smtp_host','SMTP Host'],['smtp_port','SMTP Port'],['smtp_user','SMTP Username'],['smtp_from','From Email']] as [$k,$l]) echo '<div class="form-group"><label>'.esc_html($l).'</label><input name="'.$k.'" class="form-control" value="'.esc_attr((string)get_setting($k,'')).'"></div>'; echo '<div class="form-group"><label>SMTP Password (leave blank to keep)</label><input type="password" name="smtp_pass" class="form-control"></div><button class="btn btn-primary">Save Mail Settings</button></form><hr><form method="post" class="form-inline">'.nexa_csrf_field().'<input name="test_to" type="email" required class="form-control" placeholder="you@example.com"> <button name="do" value="test" class="btn btn-success">Send Test Email</button></form><h4>Mail Log</h4><table class="table table-striped"><thead><tr><th>When</th><th>To</th><th>Subject</th><th>Status</th></tr></thead><tbody>';
    foreach(query("SELECT * FROM mail_log ORDER BY id DESC LIMIT 30") as $r) echo '<tr><td>'.esc_html($r['created_at']).'</td><td>'.esc_html($r['recipient']).'</td><td>'.esc_html($r['subject']).'</td><td>'.esc_html($r['status']).'</td></tr>';
    echo '</tbody></table><p class="text-muted">Other plugins can send mail with <code>nexa_mail($to,$subject,$body)</code> and it is logged here.</p>'; }

